llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Brigatinib, a piperazine-containing anilinopyrimidine kinase inhibitor structurally similar to the query, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Linezolid has 100% absolute oral bioavailability at an oral dose of 375 mg in patients, demonstrating that small polar oral drugs with basic centers can achieve complete absorption; supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide in normal subjects has an absolute oral bioavailability of 32 ± 7%, above the 20% threshold, despite first-pass metabolism; supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Paliperidone ER has 28% absolute oral bioavailability in healthy volunteers, above the 20% threshold, supporting high F even for a formulation with reduced colonic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Rifapentine has 70% absolute oral bioavailability after a 600 mg dose in healthy volunteers, supporting high F for a large lipophilic oral drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to oral bioavailability above 20%: close kinase-inhibitor analogue brigatinib 46%, linezolid ~100%, encainide ~32%, paliperidone 28%, and rifapentine 70%. No affirmative threshold-relevant evidence supports F < 20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is provided; prediction relies on transferable analogues.",
    "Two records under Molecule 1 (C33, C13) refer to GSK1322322 and do not match the provided brigatinib SMILES; they were excluded.",
    "Encainide shows wide interindividual F variability (7-82%), so first-pass metabolism could be a liability, but mean values remain above 20%.",
    "Paliperidone ER F is 28%, close to the threshold, and formulation-dependent absorption could affect transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

